7	import {
8	  sanitizeEnvironment,
9	  getSecureSanitizationConfig,
10	  type EnvironmentSanitizationConfig,
11	} from './environmentSanitization.js';
12	
13	/**
14	 * Request for preparing a command to run in a sandbox.
15	 */
16	export interface SandboxRequest {
17	  /** The program to execute. */
18	  command: string;
19	  /** Arguments for the program. */
20	  args: string[];
21	  /** The working directory. */
22	  cwd: string;
23	  /** Environment variables to be passed to the program. */
24	  env: NodeJS.ProcessEnv;
25	  /** Optional sandbox-specific configuration. */
26	  config?: {
27	    sanitizationConfig?: Partial<EnvironmentSanitizationConfig>;
28	    allowedPaths?: string[];
29	    networkAccess?: boolean;
30	  };
31	}
32	
33	/**
34	 * A command that has been prepared for sandboxed execution.
35	 */
36	export interface SandboxedCommand {
37	  /** The program or wrapper to execute. */
38	  program: string;
39	  /** Final arguments for the program. */
40	  args: string[];
41	  /** Sanitized environment variables. */
42	  env: NodeJS.ProcessEnv;
43	  /** The working directory. */
44	  cwd?: string;
45	}
46	
47	/**
48	 * Interface for a service that prepares commands for sandboxed execution.
49	 */
50	export interface SandboxManager {
51	  /**
52	   * Prepares a command to run in a sandbox, including environment sanitization.
53	   */
54	  prepareCommand(req: SandboxRequest): Promise<SandboxedCommand>;
55	}
56	
57	/**
58	 * A no-op implementation of SandboxManager that silently passes commands
59	 * through while applying environment sanitization.
60	 */
61	export class NoopSandboxManager implements SandboxManager {
62	  /**
63	   * Prepares a command by sanitizing the environment and passing through
64	   * the original program and arguments.
65	   */
66	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
67	    const sanitizationConfig = getSecureSanitizationConfig(
68	      req.config?.sanitizationConfig,
69	    );
70	
71	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
72	
73	    return {
74	      program: req.command,
75	      args: req.args,
76	      env: sanitizedEnv,
77	    };
78	  }
79	}
80	
81	/**
82	 * SandboxManager that implements actual sandboxing.
83	 */
84	export class LocalSandboxManager implements SandboxManager {
85	  async prepareCommand(_req: SandboxRequest): Promise<SandboxedCommand> {
86	    throw new Error('Tool sandboxing is not yet implemented.');
87	  }
88	}
89	
90	export { createSandboxManager } from './sandboxManagerFactory.js';
