7	import fs from 'node:fs';
8	import path from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	import type {
11	  SandboxManager,
12	  SandboxRequest,
13	  SandboxedCommand,
14	} from './sandboxManager.js';
15	import {
16	  sanitizeEnvironment,
17	  type EnvironmentSanitizationConfig,
18	} from './environmentSanitization.js';
19	import { debugLogger } from '../utils/debugLogger.js';
20	import { spawnAsync } from '../utils/shell-utils.js';
21	
22	const __filename = fileURLToPath(import.meta.url);
23	const __dirname = path.dirname(__filename);
24	
25	/**
26	 * A SandboxManager implementation for Windows that uses Restricted Tokens,
27	 * Job Objects, and Low Integrity levels for process isolation.
28	 * Uses a native C# helper to bypass PowerShell restrictions.
29	 */
30	export class WindowsSandboxManager implements SandboxManager {
31	  private readonly helperPath: string;
32	  private readonly platform: string;
33	  private initialized = false;
34	  private readonly lowIntegrityCache = new Set<string>();
35	
36	  constructor(platform: string = process.platform) {
37	    this.platform = platform;
38	    this.helperPath = path.resolve(__dirname, 'scripts', 'GeminiSandbox.exe');
39	  }
40	
41	  private async ensureInitialized(): Promise<void> {
42	    if (this.initialized) return;
43	    if (this.platform !== 'win32') {
44	      this.initialized = true;
45	      return;
46	    }
47	
48	    try {
49	      if (!fs.existsSync(this.helperPath)) {
50	        debugLogger.log(
51	          `WindowsSandboxManager: Helper not found at ${this.helperPath}. Attempting to compile...`,
52	        );
53	        // If the exe doesn't exist, we try to compile it from the .cs file
54	        const sourcePath = this.helperPath.replace(/\.exe$/, '.cs');
55	        if (fs.existsSync(sourcePath)) {
56	          const systemRoot = process.env['SystemRoot'] || 'C:\\Windows';
57	          const cscPaths = [
58	            'csc.exe', // Try in PATH first
59	            path.join(
60	              systemRoot,
61	              'Microsoft.NET',
62	              'Framework64',
63	              'v4.0.30319',
64	              'csc.exe',
65	            ),
66	            path.join(
67	              systemRoot,
68	              'Microsoft.NET',
69	              'Framework',
70	              'v4.0.30319',
71	              'csc.exe',
72	            ),
73	            // Added newer framework paths
74	            path.join(
75	              systemRoot,
76	              'Microsoft.NET',
77	              'Framework64',
78	              'v4.8',
79	              'csc.exe',
80	            ),
81	            path.join(
82	              systemRoot,
83	              'Microsoft.NET',
84	              'Framework',
85	              'v4.8',
86	              'csc.exe',
87	            ),
88	            path.join(
89	              systemRoot,
90	              'Microsoft.NET',
91	              'Framework64',
92	              'v3.5',
93	              'csc.exe',
94	            ),
95	          ];
96	
97	          let compiled = false;
98	          for (const csc of cscPaths) {
99	            try {
100	              debugLogger.log(
101	                `WindowsSandboxManager: Trying to compile using ${csc}...`,
102	              );
103	              // We use spawnAsync but we don't need to capture output
104	              await spawnAsync(csc, ['/out:' + this.helperPath, sourcePath]);
105	              debugLogger.log(
106	                `WindowsSandboxManager: Successfully compiled sandbox helper at ${this.helperPath}`,
107	              );
108	              compiled = true;
109	              break;
110	            } catch (e) {
111	              debugLogger.log(
112	                `WindowsSandboxManager: Failed to compile using ${csc}: ${e instanceof Error ? e.message : String(e)}`,
113	              );
114	            }
115	          }
116	
117	          if (!compiled) {
118	            debugLogger.log(
119	              'WindowsSandboxManager: Failed to compile sandbox helper from any known CSC path.',
120	            );
121	          }
122	        } else {
123	          debugLogger.log(
124	            `WindowsSandboxManager: Source file not found at ${sourcePath}. Cannot compile helper.`,
125	          );
126	        }
127	      } else {
128	        debugLogger.log(
129	          `WindowsSandboxManager: Found helper at ${this.helperPath}`,
130	        );
131	      }
132	    } catch (e) {
133	      debugLogger.log(
134	        'WindowsSandboxManager: Failed to initialize sandbox helper:',
135	        e,
136	      );
137	    }
138	
139	    this.initialized = true;
140	  }
141	
142	  /**
143	   * Prepares a command for sandboxed execution on Windows.
144	   */
145	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
146	    await this.ensureInitialized();
147	
148	    const sanitizationConfig: EnvironmentSanitizationConfig = {
149	      allowedEnvironmentVariables:
150	        req.config?.sanitizationConfig?.allowedEnvironmentVariables ?? [],
151	      blockedEnvironmentVariables:
152	        req.config?.sanitizationConfig?.blockedEnvironmentVariables ?? [],
153	      enableEnvironmentVariableRedaction:
154	        req.config?.sanitizationConfig?.enableEnvironmentVariableRedaction ??
155	        true,
156	    };
157	
158	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
159	
160	    // 1. Handle filesystem permissions for Low Integrity
161	    // Grant "Low Mandatory Level" write access to the CWD.
162	    await this.grantLowIntegrityAccess(req.cwd);
163	
164	    // Grant "Low Mandatory Level" read access to allowedPaths.
165	    if (req.config?.allowedPaths) {
166	      for (const allowedPath of req.config.allowedPaths) {
167	        await this.grantLowIntegrityAccess(allowedPath);
168	      }
169	    }
170	
171	    // 2. Construct the helper command
172	    // GeminiSandbox.exe <network:0|1> <cwd> <command> [args...]
173	    const program = this.helperPath;
174	
175	    // If the command starts with __, it's an internal command for the sandbox helper itself.
176	    const args = [
177	      req.config?.networkAccess ? '1' : '0',
178	      req.cwd,
179	      req.command,
180	      ...req.args,
181	    ];
182	
183	    return {
184	      program,
185	      args,
186	      env: sanitizedEnv,
187	    };
188	  }
189	
190	  /**
191	   * Grants "Low Mandatory Level" access to a path using icacls.
192	   */
193	  private async grantLowIntegrityAccess(targetPath: string): Promise<void> {
194	    if (this.platform !== 'win32') {
195	      return;
196	    }
197	
198	    const resolvedPath = path.resolve(targetPath);
199	    if (this.lowIntegrityCache.has(resolvedPath)) {
200	      return;
201	    }
202	
203	    // Never modify integrity levels for system directories
204	    const systemRoot = process.env['SystemRoot'] || 'C:\\Windows';
205	    const programFiles = process.env['ProgramFiles'] || 'C:\\Program Files';
206	    const programFilesX86 =
207	      process.env['ProgramFiles(x86)'] || 'C:\\Program Files (x86)';
208	
209	    if (
210	      resolvedPath.toLowerCase().startsWith(systemRoot.toLowerCase()) ||
211	      resolvedPath.toLowerCase().startsWith(programFiles.toLowerCase()) ||
212	      resolvedPath.toLowerCase().startsWith(programFilesX86.toLowerCase())
213	    ) {
214	      return;
215	    }
216	
217	    try {
218	      await spawnAsync('icacls', [resolvedPath, '/setintegritylevel', 'Low']);
219	      this.lowIntegrityCache.add(resolvedPath);
220	    } catch (e) {
221	      debugLogger.log(
222	        'WindowsSandboxManager: icacls failed for',
223	        resolvedPath,
224	        e,
225	      );
226	    }
227	  }
228	}
