21	export function createSandboxManager(
22	  sandbox: SandboxConfig | undefined,
23	  workspace: string,
24	): SandboxManager {
25	  const isWindows = os.platform() === 'win32';
26	
27	  if (
28	    isWindows &&
29	    (sandbox?.enabled || sandbox?.command === 'windows-native')
30	  ) {
31	    return new WindowsSandboxManager();
32	  }
33	
34	  if (sandbox?.enabled) {
35	    if (os.platform() === 'linux') {
36	      return new LinuxSandboxManager({ workspace });
37	    }
38	    if (os.platform() === 'darwin') {
39	      return new MacOsSandboxManager({ workspace });
40	    }
41	    return new LocalSandboxManager();
42	  }
43	
44	  return new NoopSandboxManager();
45	}
